DO $outbox_catalog$ BEGIN
 IF (SELECT count(*) FROM (SELECT a.attname::text AS column_name,t.typname::text AS type_name,a.attnotnull AS not_null FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid WHERE a.attrelid='public."NotificationOutbox"'::regclass AND a.attnum>0 AND NOT a.attisdropped) actual)<>14 OR EXISTS(SELECT FROM (VALUES ('id','text',true),('channel','text',true),('recipient','text',true),('subject','text',true),('payload','jsonb',true),('status','NotificationStatus',true),('attempts','int4',true),('maxAttempts','int4',true),('nextAttemptAt','timestamp',true),('processedAt','timestamp',false),('error','text',false),('idempotencyKey','text',false),('createdAt','timestamp',true),('updatedAt','timestamp',true)) expected(column_name,type_name,not_null) WHERE NOT EXISTS(SELECT FROM (SELECT a.attname::text AS column_name,t.typname::text AS type_name,a.attnotnull AS not_null FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid WHERE a.attrelid='public."NotificationOutbox"'::regclass AND a.attnum>0 AND NOT a.attisdropped) actual WHERE actual.column_name=expected.column_name AND actual.type_name=expected.type_name AND actual.not_null=expected.not_null)) THEN RAISE EXCEPTION 'OUTBOX_ACTUAL_CATALOG_MISMATCH'; END IF;
END $outbox_catalog$;
SELECT a.attname::text AS column_name,t.typname::text AS type_name,a.attnotnull AS not_null FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid WHERE a.attrelid='public."NotificationOutbox"'::regclass AND a.attnum>0 AND NOT a.attisdropped ORDER BY a.attnum;
SELECT id, jsonb_typeof(payload)='object' AS payload_object, jsonb_typeof(payload->'template')='string' AS template_string, coalesce(payload->>'template','') IN('BOOKING_CONFIRMATION','BOOKING_STATUS') AS template_allowlisted, jsonb_typeof(payload->'params')='object' AS params_object, jsonb_typeof(payload->'params'->'referenceNumber')='string' AS reference_string, coalesce(payload->'params'->>'referenceNumber','')=ANY(ARRAY['FWS-2026-53YFS3','FWS-2026-5LA6DA']::text[]) AS reference_owned FROM public."NotificationOutbox" WHERE id=ANY(ARRAY['cmvxtcxf20008q4f4hr0mqb79','cmvxzb3eb0006ucf4icuoxdcu','cmvxzb3g70008ucf4tpebixcr','cmvz42161000o70f47jyl8myp']::text[]) ORDER BY id;
DO $outbox_shape$ BEGIN
 IF EXISTS(SELECT FROM public."NotificationOutbox" WHERE id=ANY(ARRAY['cmvxtcxf20008q4f4hr0mqb79','cmvxzb3eb0006ucf4icuoxdcu','cmvxzb3g70008ucf4tpebixcr','cmvz42161000o70f47jyl8myp']::text[]) AND (jsonb_typeof(payload) IS DISTINCT FROM 'object' OR jsonb_typeof(payload->'template') IS DISTINCT FROM 'string' OR jsonb_typeof(payload->'params') IS DISTINCT FROM 'object' OR jsonb_typeof(payload->'params'->'referenceNumber') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'OWNED_OUTBOX_PAYLOAD_SHAPE_MISMATCH'; END IF;
END $outbox_shape$;
